package cn.breezeth.kaleidoscope_grilling;
import net.minecraft.world.item.Item;import net.minecraft.world.level.block.CropBlock;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.block.state.StateDefinition;import net.minecraft.world.level.block.state.properties.BlockStateProperties;import net.minecraft.world.level.block.state.properties.IntegerProperty;
public final class SweetPotatoCropBlock extends CropBlock{public static final IntegerProperty AGE=BlockStateProperties.AGE_3;public SweetPotatoCropBlock(Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(AGE,0));}@Override public IntegerProperty getAgeProperty(){return AGE;}@Override public int getMaxAge(){return 3;}@Override protected Item getBaseSeedId(){return ModItems.SWEET_POTATO.get();}@Override protected void createBlockStateDefinition(StateDefinition.Builder<net.minecraft.world.level.block.Block,BlockState>b){b.add(AGE);}}
